//! Desktop and iOS agree, proven on the iOS app's own fixtures.
//!
//! The first three were generated by the tagger's reference pipeline:
//! Hugging Face's `BertTokenizer`, the model's labels at the 0.98
//! threshold, and `js/reconstruct.js`. The iOS suite runs its Swift against
//! them (`CleanupTaggerTests.swift`), and this runs the Rust. The fourth is
//! written by the Swift guard itself (`fixtures/guard_reference.swift`), as
//! the reference pipeline has no guard.

use serde::Deserialize;

use super::tokenizer::{CLS, SEP, UNKNOWN};
use super::{
    Chunk, CleanupGuard, EditPlan, Policy, Proposal, ProtectedTerms, Tokenizer, Words,
    WrongVocabularySize, render,
};

const VOCABULARY: &str =
    include_str!("../../../ios/HEXKeyboard/CleanupTagger/HexCleanupTaggerVocab.txt");
const TOKENIZER: &str = include_str!("../../../ios/HEXMobileTests/Fixtures/cleanup-tokenizer.json");
const RECONSTRUCT: &str =
    include_str!("../../../ios/HEXMobileTests/Fixtures/cleanup-reconstruct.json");
const HANDWRITTEN: &str =
    include_str!("../../../ios/HEXMobileTests/Fixtures/cleanup-tagger-handwritten.json");
const GUARD: &str = include_str!("fixtures/guard-reference.json");

#[derive(Deserialize)]
struct Cases<Case> {
    cases: Vec<Case>,
}

#[derive(Deserialize)]
struct TokenizerCase {
    word: String,
    ids: Vec<i32>,
}

#[derive(Deserialize)]
struct ReconstructCase {
    words: Vec<String>,
    labels: Vec<u8>,
    output: String,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct HandwrittenCase {
    id: u32,
    input: String,
    /// The model's labels at the threshold, rebuilt by the reference.
    expected: String,
    /// The hand-written ideal cleanup.
    target: String,
    labels: Vec<u8>,
    p_delete: Vec<f64>,
    checkpoint_p_delete: Vec<f64>,
}

/// What the iOS guard decided for some words, and what iOS rebuilt.
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
pub(super) struct GuardCase {
    pub(super) words: Vec<String>,
    pub(super) p_delete: Vec<f64>,
    pub(super) terms: Vec<String>,
    labels: Vec<u8>,
    output: String,
}

fn cases<Case: for<'de> Deserialize<'de>>(fixture: &str) -> Vec<Case> {
    let fixture: Cases<Case> = serde_json::from_str(fixture).unwrap();
    fixture.cases
}

pub(super) fn guard_cases() -> Vec<GuardCase> {
    cases(GUARD)
}

fn tokenizer() -> Tokenizer {
    Tokenizer::from_vocabulary(VOCABULARY).unwrap()
}

fn flags(labels: &[u8]) -> Vec<bool> {
    labels.iter().map(|&label| label == 1).collect()
}

/// One proposal per word, as sure as the fixture's P(DELETE).
pub(super) fn proposals(words: &Words, p_delete: &[f64]) -> Vec<Proposal> {
    assert_eq!(words.len(), p_delete.len());
    p_delete
        .iter()
        .enumerate()
        .map(|(index, &p)| Proposal::delete(words.span(index..index + 1).unwrap(), p))
        .collect()
}

/// Which words a policy removes, and the text that leaves.
fn guarded(
    policy: Policy,
    words: &Words,
    p_delete: &[f64],
    terms: &[String],
) -> (Vec<bool>, String) {
    let protected = ProtectedTerms::new(terms.iter().map(String::as_str));
    let guard = CleanupGuard {
        policy,
        protected: &protected,
    };
    let plan = guard.admit(words, &proposals(words, p_delete)).plan;
    (plan.deletes(words.len()), render(words, &plan))
}

#[test]
fn the_tokenizer_matches_hugging_face_on_every_fixture_word() {
    let cases: Vec<TokenizerCase> = cases(TOKENIZER);
    let tokenizer = tokenizer();
    let failures: Vec<String> = cases
        .iter()
        .filter(|case| tokenizer.encode(&case.word) != case.ids)
        .map(|case| {
            let got = tokenizer.encode(&case.word);
            format!("{:?}: {got:?} != {:?}", case.word, case.ids)
        })
        .collect();
    assert_eq!(cases.len(), 1891);
    assert_eq!(
        failures,
        Vec::<String>::new(),
        "{} of {} words",
        failures.len(),
        cases.len()
    );
}

/// The iOS suite's own cases (`testTokenizerSplitsSpecialTokensAndStripsAccents`).
#[test]
fn the_tokenizer_splits_special_tokens_and_strips_accents() {
    let tokenizer = tokenizer();
    let encode = |word: &str| tokenizer.encode(word);
    assert_eq!(encode("[CLS]"), [CLS]);
    assert_eq!(
        encode("x[SEP]y"),
        [encode("x"), vec![SEP], encode("y")].concat()
    );
    assert_eq!(encode("Café"), encode("cafe"));
    assert_eq!(encode("e\u{301}clair"), encode("eclair"));
    assert_eq!(encode(&"a".repeat(101)), [UNKNOWN]);
    assert_eq!(encode("4pm?"), [encode("4pm"), encode("?")].concat());
    assert_eq!(encode("\u{200B}"), Vec::<i32>::new());
    assert_eq!(
        encode("[cls]"),
        [encode("["), encode("cls"), encode("]")].concat()
    );
}

#[test]
fn a_vocabulary_of_another_size_is_refused_and_line_endings_do_not_matter() {
    let short = VOCABULARY.lines().take(100).collect::<Vec<_>>().join("\n");
    let error = Tokenizer::from_vocabulary(&short).unwrap_err();
    assert_eq!(error, WrongVocabularySize { lines: 100 });
    assert_eq!(
        error.to_string(),
        "the cleanup vocabulary has 100 tokens, not 30522"
    );

    let unix = VOCABULARY.replace("\r\n", "\n");
    let windows = unix.replace('\n', "\r\n");
    let (unix, windows) = (
        Tokenizer::from_vocabulary(&unix).unwrap(),
        Tokenizer::from_vocabulary(&windows).unwrap(),
    );
    for word in ["Hey", "Tim,", "unbelievably", "4pm?"] {
        assert_eq!(unix.encode(word), windows.encode(word));
        assert!(!unix.encode(word).contains(&UNKNOWN));
    }
}

#[test]
fn a_transcript_becomes_chunks_that_cover_every_word() {
    let cases: Vec<HandwrittenCase> = cases(HANDWRITTEN);
    let text: Vec<&str> = cases
        .iter()
        .take(30)
        .map(|case| case.input.as_str())
        .collect();
    let words = Words::new(text.join(" "));
    let chunks: Vec<Chunk> = tokenizer().chunks(&words);
    assert!(words.len() > 200);
    assert!(chunks.len() > 1);

    let mut covered = Vec::new();
    for chunk in &chunks {
        let ids = chunk.input_ids();
        assert!([16, 32, 64, 128].contains(&ids.len()));
        assert_eq!(ids[0], CLS);
        assert_eq!(ids[chunk.length() - 1], SEP);
        assert!(ids[chunk.length()..].iter().all(|&id| id == 0));
        // A logit of 9 everywhere proposes every word the chunk holds.
        let proposed = chunk.proposals(&vec![9.0; chunk.length()]).unwrap();
        covered.extend(proposed.iter().flat_map(|proposal| proposal.at().range()));
    }
    assert_eq!(covered, (0..words.len()).collect::<Vec<_>>());
}

#[test]
fn rendering_matches_the_javascript_reference_on_every_fixture_case() {
    let cases: Vec<ReconstructCase> = cases(RECONSTRUCT);
    let mut failures = Vec::new();
    for case in &cases {
        let words = Words::new(case.words.join(" "));
        assert!(words.iter().eq(case.words.iter().map(String::as_str)));
        let output = render(&words, &EditPlan::deleting(&words, &flags(&case.labels)));
        if output != case.output {
            failures.push(format!(
                "{:?} {:?}: {output:?} != {:?}",
                case.words, case.labels, case.output
            ));
        }
    }
    assert_eq!(cases.len(), 670);
    assert_eq!(
        failures,
        Vec::<String>::new(),
        "{} of {} cases",
        failures.len(),
        cases.len()
    );
}

/// The reference pipeline has no guard: the model's own labels, rebuilt.
#[test]
fn the_handwritten_sentences_rebuild_as_the_reference_pipeline_rebuilt_them() {
    let cases: Vec<HandwrittenCase> = cases(HANDWRITTEN);
    assert_eq!(cases.len(), 137);
    let mut count = 0;
    for case in &cases {
        let words = Words::new(case.input.as_str());
        assert_eq!(
            words.len(),
            case.labels.len(),
            "#{} splits into the reference's words",
            case.id
        );
        let output = render(&words, &EditPlan::deleting(&words, &flags(&case.labels)));
        assert_eq!(output, case.expected, "#{}", case.id);
        count += words.len();
    }
    assert_eq!(count, 1128);
}

/// The iOS guard, word for word: for the hand-written sentences at both of
/// their recorded probability sets, for random markings of them, and for
/// sentences picked to reach every rule.
#[test]
fn the_guard_decides_what_the_ios_guard_decides_on_every_reference_case() {
    let cases = guard_cases();
    let mut failures = Vec::new();
    for case in &cases {
        let words = Words::new(case.words.join(" "));
        assert!(words.iter().eq(case.words.iter().map(String::as_str)));
        let (deletes, output) = guarded(Policy::IOS, &words, &case.p_delete, &case.terms);
        if deletes != flags(&case.labels) || output != case.output {
            failures.push(format!(
                "{:?} {:?} {:?}: {deletes:?} {output:?} != {:?} {:?}",
                case.words, case.p_delete, case.terms, case.labels, case.output
            ));
        }
    }
    assert_eq!(cases.len(), 726);
    assert_eq!(
        failures,
        Vec::<String>::new(),
        "{} of {} cases",
        failures.len(),
        cases.len()
    );
}

/// The tagger's recorded probabilities through the guard and the renderer,
/// against the hand-written ideal. The eight misses are the tagger's and the
/// iOS guard's own (the same eight on iOS), not the port's.
#[test]
fn the_handwritten_sentences_clean_up_as_they_do_on_ios() {
    let cases: Vec<HandwrittenCase> = cases(HANDWRITTEN);
    for (recorded, on_target) in [(false, 129), (true, 129)] {
        let mut ios = 0;
        let mut desktop = 0;
        for case in &cases {
            let words = Words::new(case.input.as_str());
            let p_delete = if recorded {
                &case.checkpoint_p_delete
            } else {
                &case.p_delete
            };
            ios += usize::from(guarded(Policy::IOS, &words, p_delete, &[]).1 == case.target);
            let output = guarded(Policy::DESKTOP, &words, p_delete, &[]).1;
            if case.id == 39 {
                // The old target drops the noun before "the green one".
                // Desktop deliberately keeps this unresolved correction.
                assert_eq!(output, case.input);
            }
            desktop += usize::from(output == case.target);
        }
        assert_eq!((ios, desktop), (on_target, on_target - 1));
    }
}

/// The desktop policy only ever keeps more than the iOS guard does.
#[test]
fn the_desktop_policy_removes_nothing_the_ios_guard_keeps() {
    let mut kept_more = 0;
    for case in guard_cases() {
        let words = Words::new(case.words.join(" "));
        let (ios, _) = guarded(Policy::IOS, &words, &case.p_delete, &case.terms);
        let (desktop, _) = guarded(Policy::DESKTOP, &words, &case.p_delete, &case.terms);
        assert!(
            desktop
                .iter()
                .zip(&ios)
                .all(|(desktop, ios)| *ios || !desktop),
            "{:?} {:?}",
            case.words,
            case.p_delete
        );
        kept_more += usize::from(desktop != ios);
    }
    assert!(kept_more > 0);
}
